using FluentValidation; using MediatR; using Microsoft.OpenApi.Models; using Serilog; using InventorySystem.Infrastructure; using InventorySystem.Infrastructure.Persistence; using InventorySystem.API.Middleware; using InventorySystem.Application.Features.Products.Commands;
Log.Logger=new LoggerConfiguration().WriteTo.Console().CreateBootstrapLogger(); var builder=WebApplication.CreateBuilder(args); builder.Host.UseSerilog((ctx,lc)=>lc.ReadFrom.Configuration(ctx.Configuration).WriteTo.Console()); builder.Services.AddInfrastructure(builder.Configuration); builder.Services.AddMediatR(x=>x.RegisterServicesFromAssembly(typeof(CreateProductCommand).Assembly)); builder.Services.AddValidatorsFromAssembly(typeof(CreateProductCommand).Assembly); builder.Services.AddControllers(); builder.Services.AddEndpointsApiExplorer(); builder.Services.AddSwaggerGen(c=>c.AddSecurityDefinition("Bearer",new OpenApiSecurityScheme{In=ParameterLocation.Header,Name="Authorization",Type=SecuritySchemeType.Http,Scheme="bearer"})); builder.Services.AddCors(o=>o.AddPolicy("AllowAll",p=>p.AllowAnyOrigin().AllowAnyHeader().AllowAnyMethod())); var app=builder.Build(); using(var scope=app.Services.CreateScope()) await DbSeeder.SeedAsync(app.Services); app.UseSwagger(); app.UseSwaggerUI(); app.UseMiddleware<ExceptionMiddleware>(); app.UseSerilogRequestLogging(); app.UseCors("AllowAll"); app.UseAuthentication(); app.UseAuthorization(); app.MapControllers(); app.Run();
